if (this.featureToggles.opfUseDestroyRef) {
  this.cartPoNumber$
    .pipe(takeUntilDestroyed(this.destroyRef))
    .subscribe((poNumber) => {
      this.poNumberValue = poNumber;
      this.form.patchValue({ poNumber });
    });
}

if (this.featureToggles.opfUseDestroyRef) {
  this.service.pickupNoDefaultAddress$
    .pipe(takeUntilDestroyed(this.destroyRef))
    .subscribe(() => {
      this.isEditBillingAddress = true;
      this.isAddingBillingAddressInProgress = true;
    });
}

if (this.featureToggles.opfUseDestroyRef) {
  this.giftCardFacade
    .isGiftCardCoveredTotalAmount(this.cart$)
    .pipe(takeUntilDestroyed(this.destroyRef))
    .subscribe((isCovered) => {
      this.opfPaymentEventsService.emitIsGiftCardCoveredTotalAmountEvent(
        isCovered
      );
    });

  // Close gift card form when other payment options are selected
  // selectedPaymentOptionId is -1 for saved payment details.
  this.opfMetadataStoreService
    .getOpfMetadataState()
    .pipe(takeUntilDestroyed(this.destroyRef))
    .subscribe((x) => {
      if (
        (x.selectedPaymentOptionId ?? 0) >= -1 &&
        this.showGiftCardForm()
      ) {
        this.giftCardForm.reset();
        this.toggleGiftCardForm();
      }
    });

  if (this.outlet?.context$) {
    this.outlet.context$
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe((context) => {
        this.isBillingAddressPresent$ = context?.disabled;
      });
  }
}

@include forFeature('searchBoxRecentSearchesRemoval') {
  .recent-searches {
    position: relative;

    cx-recent-searches-header .recentSearches-header {
      @include media-breakpoint-down(sm) {
        display: flex;
        align-items: center;

        button {
          min-height: 20px;
          padding: 0;
        }
      }
    }
  }
}

@include forFeature('searchBoxRecentSearchesRemoval') {
  .recent-searches cx-recent-searches-header .clear-recent-searches-btn {
    display: none;
    position: absolute;
    padding: 0;
    min-height: 21px;
    @include media-breakpoint-down(sm) {
      display: block;
      right: 0;
      top: 0;
    }
  }
}

